import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Missing-Values-for-Summary-Variables.md","filePath":"manual-en/CTABLES-Missing-Values-for-Summary-Variables.md","lastUpdated":1785684581000}'),i={name:"manual-en/CTABLES-Missing-Values-for-Summary-Variables.md"};function r(l,e,o,n,c,u){return a(),d("div",null,[...e[0]||(e[0]=[s('<h4 id="_15-7-9-2-missing-values-for-summary-variables" tabindex="-1">15.7.9.2 Missing Values for Summary Variables <a class="header-anchor" href="#_15-7-9-2-missing-values-for-summary-variables" aria-label="Permalink to &quot;15.7.9.2 Missing Values for Summary Variables&quot;">​</a></h4><p>For summary variables, values that are valid and in included categories are analyzed, and values that are missing or in excluded categories are not analyzed, with the following exceptions:</p><ul><li>The “<code>VALIDN</code>” summary functions (<code>VALIDN</code>, <code>EVALIDN</code>, <code>UVALIDN</code>, <code>_area_ PCT.VALIDN</code>, and <code>U _area_ PCT.VALIDN</code>) only count valid values in included categories (not missing values in included categories).</li><li>The “<code>TOTALN</code>” summary functions (<code>TOTALN</code>, <code>ETOTALN</code>, <code>UTOTALN</code>, <code>_area_ PCT.TOTALN</code>), and <code>U _area_ PCT.TOTALN</code> count all values (valid and missing) in included categories and missing (but not valid) values in excluded categories.</li></ul><p>For categorical variables, system-missing values are never in included categories. For scale variables, there is no notion of included and excluded categories, so all values are effectively included.</p><p>The following table provides another view of the above rules:</p><table tabindex="0"><thead><tr><th></th><th>VALIDN</th><th>other</th><th>TOTALN</th></tr></thead><tbody><tr><td>Categorical variables:</td><td></td><td></td><td></td></tr><tr><td>Valid values in included categories</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>Missing values in included categories</td><td>—</td><td>yes</td><td>yes</td></tr><tr><td>Missing values in excluded categories</td><td>—</td><td>—</td><td>yes</td></tr><tr><td>Valid values in excluded categories</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Scale variables:</td><td></td><td></td><td></td></tr><tr><td>Valid values</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>User- or system-missing values</td><td>—</td><td>yes</td><td>yes</td></tr></tbody></table>',6)])])}const g=t(i,[["render",r]]);export{v as __pageData,g as default};
